        private static object? __tsonic_module_init_core()
        {
            Node_modules_Tsumo_engine_src_models.__tsonic_module_init();
            Node_modules_Tsumo_engine_src_diagnostics.__tsonic_module_init();
            Node_modules_Tsumo_engine_src_template_values.__tsonic_module_init();
            return null;
        }
        public static void __tsonic_module_init()
        {
            _ = __tsonic_module_initialization.Value;
        }
